const simple=r=>({path:r.path,bytes:r.bytes,sha256:r.sha256});
pin({path:Q+'/SOURCE_DEPENDENCIES.json',bytes:136111,sha256:'beb9357310be6b4157fc64c99552f67a2854540e954f7a9bcced7188b3adba17'});
pin({path:Q+'/SOURCE_IDENTITIES.json',bytes:21666,sha256:'f03f588103a9f4c2ec0c6183b75221a72187aa9c7fead7068c07fc9293b99b26'});
const D=JSON.parse(read(Q+'/SOURCE_DEPENDENCIES.json').body), S=JSON.parse(read(Q+'/SOURCE_IDENTITIES.json').body), M=new Map(D.protected_files.map(r=>[r.path,r]));
need(M.size===150,'count');D.protected_files.forEach((r,i)=>{need(r.role==='dep_'+String(i+1).padStart(4,'0')&&r.path===r.identity.path,'row');pin(r.identity);});need(eq([...M.keys()],[...M.keys()].sort()),'sort');
const old=JSON.parse(read(P+'/SOURCE_DEPENDENCIES.json').body), omit=r=>Object.fromEntries(Object.entries(r).filter(([k])=>k!=='role'));
