for(const[k,i]of Object.entries(S.source_text_counterparts.published))need(read(i.path).body.equals(read(S.premise_texts[k].path).body),'pair');
const final=['ANALYTIC_RESULT.json','AUTHOR_CHECKS.json','CANONICAL_EQUALITY_SYNTHESIS.md','COUPLED_EQUALITY_REDUCTION.md','DEPENDENCY_NOTES.md','HANDOFF.json','HANDOFF.md','NEUTRAL_COMPONENT_INCIDENCE.md','SOURCE_DEPENDENCIES.json','SOURCE_IDENTITIES.json'];
const stage=process.env.RI151_STAGE||'preseal8',expected=stage==='final10'?final:final.filter(n=>!['AUTHOR_CHECKS.json','HANDOFF.json'].includes(n));
need(eq(fs.readdirSync(Q).sort(),expected),'current namespace');
const payloads=expected.map(n=>simple(read(Q+'/'+n)));
let sourceRefs=0;for(const n of ['CANONICAL_EQUALITY_SYNTHESIS.md','COUPLED_EQUALITY_REDUCTION.md','NEUTRAL_COMPONENT_INCIDENCE.md']){const txt=read(Q+'/'+n).body.toString('utf8');need(!/^(<{7}|={7}|>{7})( |$)/m.test(txt),'conflict');need(!/[ \t]+$/m.test(txt),'trailing whitespace');for(const match of txt.matchAll(/\x60(\/Volumes\/[^\x60 \n]+\.(?:md|json|py))\x60/g)){need(M.has(match[1])||expected.some(f=>Q+'/'+f===match[1]),'literal reference '+match[1]);sourceRefs++;}}
if(stage==='final10'){const h=JSON.parse(read(Q+'/HANDOFF.json').body);need(eq(h.namespace,final)&&h.payloads.length===9,'current seal');need(eq(h.payloads.map(x=>p.basename(x.path)).sort(),final.filter(n=>n!=='HANDOFF.json')),'current payload coverage');h.payloads.forEach(pin);pin(h.assignment);pin(h.accepted_predecessor);}
const before=[...cache.values()].map(simple);cache.clear();before.forEach(pin);
console.log(JSON.stringify({schema:'ri151-author-administrative-check-v1',status:'MATCH_NOT_PROOF_ACCEPTANCE',stage,dependencies:150,selected_bytes:D.protected_files.reduce((n,r)=>n+r.identity.bytes,0),inherited:129,administrative_bodies:45,historical_typed_refs:734,premise_refs:66,predecessor_namespaces:[10,7],counterparts:4,absolute_manuscript_reference_occurrences:sourceRefs,final_fresh_identity_rechecks:before.length,current_payloads:payloads,scientific_execution:false},null,2));
